import { createClient } from 'supabase';
const N=(x:any)=>x===null||x===undefined||x===''?null:Number(x);
const clamp=(x:number,a:number,b:number)=>Math.max(a,Math.min(b,x));
Deno.serve(async()=>{
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}});
 try{
  const [{data:mv,error:mve},{data:teams,error:te},{data:hist,error:he},{data:friends,error:fe}]=await Promise.all([
   sb.from('model_versions').select('id,version').eq('is_active',true).single(),
   sb.from('teams').select('id,fpl_team_id,team_code,name,elo,strength'),
   sb.from('historical_team_seasons').select('*').eq('season','2025-2026'),
   sb.from('matches').select('home_team_id,away_team_id,home_xg,away_xg,home_score,away_score,finished').eq('source','fpl_core_insights').eq('competition','friendly')
  ]);if(mve||te||he||fe)throw(mve||te||he||fe);
  const totalMatches=(hist||[]).reduce((s:any,h:any)=>s+(N(h.matches)||0),0);const totalXg=(hist||[]).reduce((s:any,h:any)=>s+(N(h.xg_for)||0),0);const lgAvg=totalMatches?totalXg/totalMatches:1.45;const avgElo=(teams||[]).reduce((s:any,t:any)=>s+(N(t.elo)||0),0)/(teams?.length||1);
  const hmap=new Map((hist||[]).map((h:any)=>[Number(h.team_code),h]));const pre=new Map<number,any>();const ensure=(id:number)=>{let a=pre.get(id);if(!a){a={matches:0,xg_matches:0,xgf:0,xga:0,gf:0,ga:0};pre.set(id,a)}return a};
  for(const m of friends||[]){if(!m.finished)continue;const hx=N(m.home_xg),ax=N(m.away_xg);if(m.home_team_id){const a=ensure(Number(m.home_team_id));a.matches++;a.gf+=N(m.home_score)||0;a.ga+=N(m.away_score)||0;if(hx!==null&&ax!==null){a.xg_matches++;a.xgf+=hx;a.xga+=ax}}if(m.away_team_id){const a=ensure(Number(m.away_team_id));a.matches++;a.gf+=N(m.away_score)||0;a.ga+=N(m.home_score)||0;if(hx!==null&&ax!==null){a.xg_matches++;a.xgf+=ax;a.xga+=hx}}}
  const asOf=new Date().toISOString();const rows:any[]=[];
  for(const t of teams||[]){const h=hmap.get(Number(t.team_code)),p=pre.get(Number(t.id));let baseFor:number,baseAgainst:number,source:string;if(h&&(N(h.matches)||0)>0){const hm=N(h.matches)||0;baseFor=((N(h.xg_for)||0)+lgAvg*6)/(hm+6);baseAgainst=((N(h.xg_against)||0)+lgAvg*6)/(hm+6);source='2025/26_PL'}else{baseFor=lgAvg*0.86;baseAgainst=lgAvg*1.14;source='promoted_baseline'}
   const elo=N(t.elo)||avgElo;const ef=clamp(Math.exp((elo-avgElo)/900),0.75,1.30);baseFor*=Math.sqrt(ef);baseAgainst/=Math.sqrt(ef);
   const pw=(p?.xg_matches||0)*0.35;const priorW=h?18:10;let xgf=baseFor,xga=baseAgainst;if(pw>0){xgf=(baseFor*priorW+(p.xgf/p.xg_matches)*pw)/(priorW+pw);xga=(baseAgainst*priorW+(p.xga/p.xg_matches)*pw)/(priorW+pw)}
   rows.push({team_id:t.id,as_of:asOf,model_version_id:mv.id,sample_matches:(N(h?.matches)||0)+(p?.matches||0),formation:null,xg_for_90:Number(xgf.toFixed(4)),xg_against_90:Number(xga.toFixed(4)),goals_for_90:h?Number(((N(h.goals_for)||0)/(N(h.matches)||1)).toFixed(4)):null,goals_against_90:h?Number(((N(h.goals_against)||0)/(N(h.matches)||1)).toFixed(4)):null,possession:h?Number(((N(h.possession_sum)||0)/(N(h.matches)||1)).toFixed(2)):null,clean_sheet_prob:null,state:{model:'team_state_v0.1',prior_source:source,league_avg_xg:Number(lgAvg.toFixed(4)),elo,elo_factor:Number(ef.toFixed(4)),historical:h?{matches:N(h.matches)||0,xgf_per_match:Number(((N(h.xg_for)||0)/(N(h.matches)||1)).toFixed(3)),xga_per_match:Number(((N(h.xg_against)||0)/(N(h.matches)||1)).toFixed(3))}:null,preseason:{matches:p?.matches||0,xg_matches:p?.xg_matches||0,xgf:p?.xg_matches?Number((p.xgf/p.xg_matches).toFixed(3)):null,xga:p?.xg_matches?Number((p.xga/p.xg_matches).toFixed(3)):null},notes:['historical rates shrunk to league mean','Elo modestly adjusts attack/defence','friendlies weighted 0.35 PL match each']}})
  }
  const {error}=await sb.from('team_state').insert(rows);if(error)throw error;return Response.json({ok:true,model_version:mv.version,as_of:asOf,teams:rows.length,league_avg_xg:Number(lgAvg.toFixed(4))});
 }catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}
});
